# Helper to create a minimal doorstop repository in a temporary directory
def create_repo_with_docs(tmp_path, docs):
    """
    Create a minimal doorstop repository with the given documents.

    :param tmp_path: Path to the temporary directory.
    :param docs: Dict mapping document names to list of (uid, text) tuples.
    """
    # Create a .doorstop.yml config file
    config = tmp_path / ".doorstop.yml"
    config.write_text("root: .\n")
    # Create each document file
    for doc_name, items in docs.items():
        doc_path = tmp_path / f"{doc_name}.yml"
        lines = []
        for uid, text in items:
            lines.append(f"{uid}: {text}")
        doc_path.write_text("\n".join(lines))
    return tmp_path

